// [Input] Persisted Chat user-message text generated by the Reflections Analyze workflow.
// [Output] An allowlisted Reflections section for preview-only rendering, or null.
// [Pos] Pure recognition seam between Reflections task prompts and Chat message presentation.
// [Sync] 2026-10-14: recognize only the first workflow H1 after the final server-owned completion anchor.

import type { StoryWorkspaceAnalysisSection } from '../../router/storyWorkspacePath';

const REFLECTIONS_COMPLETION_ANCHOR = 'Complete this Reflections analysis in this turn.';

const SECTION_BY_WORKFLOW_HEADING: Readonly<Record<string, StoryWorkspaceAnalysisSection>> = {
  '# Reflections — Recurring Themes (Echoes) Workflow': 'echoes',
  '# Reflections — Character Traits Workflow': 'traits',
  '# Reflections — Behavioral Patterns Workflow': 'patterns',
};

export function parseReflectionAnalysisPreview(
  text: string,
): StoryWorkspaceAnalysisSection | null {
  const anchorIndex = text.lastIndexOf(REFLECTIONS_COMPLETION_ANCHOR);
  if (anchorIndex < 0) return null;

  const workflowText = text.slice(anchorIndex + REFLECTIONS_COMPLETION_ANCHOR.length);
  const firstHeading = workflowText.match(/^# [^\r\n]+$/m)?.[0];
  return firstHeading ? SECTION_BY_WORKFLOW_HEADING[firstHeading] ?? null : null;
}
